//! A learning-path Exercise, through the scoring the app really has.
//!
//! `tests/path_fixtures/schedules.jsonl` is generated by `npm run paths -- gen`
//! from the packs in `src/paths/packs/`: every Exercise with target notes, as the
//! exact `ScoreSchedule` that `src/songs/schedule.ts` builds. This proves that
//! format reaches `match_attempt` and comes out meaning what it should. It says
//! **nothing about a real guitar**: the "played" onsets here are computed, with a
//! little seeded jitter, because the question is whether the Exercise is scorable,
//! not whether the detector hears it.
//!
//!   node scripts/rust-test.mjs --test path_exercises

use std::fs;
use std::path::PathBuf;

use yames_lib::instrument::Instrument;
use yames_lib::score::pass::CLEAN_TEMPO_MIN_BARS;
use yames_lib::score::{
    match_attempt, BeatMap, OnsetState, PassBar, PassResult, PassVerdict, PlayedOnset, ScheduleReport,
    ExpectedOnset, ScheduleRun, ScoreSchedule,
};
use yames_lib::session_log::Xorshift64;

#[derive(serde::Deserialize)]
struct Row {
    path: String,
    exercise: String,
    bpm: f64,
    schedule: ScoreSchedule,
}

fn rows() -> Vec<Row> {
    let file = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("path_fixtures")
        .join("schedules.jsonl");
    fs::read_to_string(&file)
        .unwrap_or_else(|e| panic!("{}: {e}. Run: npm run paths -- gen", file.display()))
        .lines()
        .map(|line| serde_json::from_str(line).expect("a schedule the app can read"))
        .collect()
}

fn beat_map(bpm: f64, beats: f64) -> BeatMap {
    let ms = 60_000.0 / bpm;
    BeatMap::from_quarter_times((0..=(beats.ceil() as usize + 1)).map(|i| i as f64 * ms).collect())
}

/// Every written onset, played at its time plus up to `jitter_ms` either way.
fn played(row: &Row, jitter_ms: f64, seed: u64) -> Vec<PlayedOnset> {
    let ms = 60_000.0 / row.bpm;
    let mut rng = Xorshift64::new(seed);
    row.schedule
        .onsets
        .iter()
        .map(|onset| PlayedOnset {
            time_ms: onset.beat * ms + ((rng.next_u64() % 2001) as f64 / 1000.0 - 1.0) * jitter_ms,
            amplitude: if onset.accent { 1.0 } else { 0.5 },
            confidence: 1.0,
        })
        .collect()
}

fn report(row: &Row, notes: &[PlayedOnset]) -> ScheduleReport {
    let weights = Instrument::ElectricGuitar.profile().score_weights;
    match_attempt(
        &row.schedule,
        &beat_map(row.bpm, row.schedule.length_beats),
        notes,
        &weights,
    )
}

fn hits(report: &ScheduleReport) -> usize {
    report
        .results
        .iter()
        .filter(|r| r.state == OnsetState::Hit)
        .count()
}

fn misses(report: &ScheduleReport) -> usize {
    report
        .results
        .iter()
        .filter(|r| r.state == OnsetState::Miss)
        .count()
}

#[test]
fn every_exercise_is_scorable_and_the_right_playing_passes() {
    let rows = rows();
    assert!(rows.len() > 80, "only {} schedules", rows.len());
    for (index, row) in rows.iter().enumerate() {
        let report = report(row, &played(row, 2.0, 1 + index as u64));
        let name = format!("{}/{}", row.path, row.exercise);
        assert_eq!(
            hits(&report),
            row.schedule.onsets.len(),
            "{name}: all written notes played, all should be hits"
        );
        assert_eq!(report.extras.len(), 0, "{name}: nothing extra was played");
        assert!(
            report.hit_completeness > 0.99,
            "{name}: hit completeness {}",
            report.hit_completeness
        );
        assert!(
            report.interval_consistency >= 0.85,
            "{name}: evenness {} at 2 ms of jitter should clear the 0.85 bar",
            report.interval_consistency
        );
    }
}

/// The pass bars use `hit_completeness` because the headline `score` ignores it
/// on guitar. If that ever changes this test still holds, and it is the reason
/// a pass bar may not be written against `score`.
#[test]
fn a_dropped_picked_note_shows_up_in_the_field_a_pass_bar_uses() {
    let mut checked = 0;
    for (index, row) in rows().iter().enumerate() {
        let picked: Vec<usize> = row
            .schedule
            .onsets
            .iter()
            .enumerate()
            .filter(|(_, o)| !o.soft)
            .map(|(i, _)| i)
            .collect();
        if picked.len() < 8 {
            continue;
        }
        let drop = picked[picked.len() / 2];
        let mut notes = played(row, 2.0, 100 + index as u64);
        notes.remove(drop);
        let report = report(row, &notes);
        let name = format!("{}/{}", row.path, row.exercise);
        assert!(misses(&report) >= 1, "{name}: a dropped note must be a miss");
        assert!(
            report.hit_completeness < 1.0,
            "{name}: hit completeness {} should fall",
            report.hit_completeness
        );
        checked += 1;
    }
    assert!(checked > 60, "only {checked} Exercises long enough to test");
}

#[test]
fn an_extra_note_shows_up_as_an_extra() {
    let rows = rows();
    let row = rows
        .iter()
        .find(|r| r.exercise == "even-eighths.open-string")
        .expect("the first Exercise of Alternate Picking");
    let mut notes = played(row, 1.0, 7);
    // Halfway between two written eighths.
    let ms = 60_000.0 / row.bpm;
    notes.push(PlayedOnset {
        time_ms: 1.25 * ms,
        amplitude: 0.5,
        confidence: 1.0,
    });
    notes.sort_by(|a, b| a.time_ms.partial_cmp(&b.time_ms).unwrap());
    let report = report(row, &notes);
    assert_eq!(report.extras.len(), 1);
}

#[test]
fn an_unheard_hammer_on_costs_nothing() {
    let rows = rows();
    let row = rows
        .iter()
        .find(|r| r.exercise == "phrases.lick-to-bend")
        .expect("a sweep lick with a hammer and two pulls");
    let mut notes = played(row, 1.0, 11);
    let soft: Vec<usize> = row
        .schedule
        .onsets
        .iter()
        .enumerate()
        .filter(|(_, o)| o.soft)
        .map(|(i, _)| i)
        .collect();
    assert_eq!(soft.len(), 3);
    for index in soft.iter().rev() {
        notes.remove(*index);
    }
    let report = report(row, &notes);
    assert_eq!(misses(&report), 0, "soft notes are never a miss");
    assert_eq!(
        report
            .results
            .iter()
            .filter(|r| r.state == OnsetState::SoftAbsent)
            .count(),
        3
    );
}

/// A variant is a schedule like any other: its notes are known, so it scores.
#[test]
fn a_variant_and_a_chain_are_scored_like_anything_else() {
    let rows = rows();
    let variants: Vec<&Row> = rows.iter().filter(|r| r.exercise.contains('#')).collect();
    assert!(variants.len() > 200, "only {} variant schedules", variants.len());

    let chain = rows
        .iter()
        .find(|r| r.exercise == "link-chains.looped-chain#key=A,progression=i-VI-III-VII")
        .expect("a chained-arpeggio Exercise, in one key and progression");
    let other = rows
        .iter()
        .find(|r| r.exercise == "link-chains.looped-chain#key=E,progression=i-VII-VI-VII")
        .expect("the same Exercise in another variant");
    for row in [chain, other] {
        assert!(row.schedule.onsets.iter().any(|o| o.soft), "a chain has hammers and pulls");
        let clean = report(row, &played(row, 2.0, 31));
        assert_eq!(hits(&clean), row.schedule.onsets.len());
        assert_eq!(misses(&clean), 0);

        // A picked note dropped in the middle of the chain is a miss, on that
        // variant's own schedule, and only one.
        let picked = row
            .schedule
            .onsets
            .iter()
            .position(|o| !o.soft && o.beat >= 8.0)
            .expect("a picked note in the second half");
        let mut notes = played(row, 2.0, 32);
        notes.remove(picked);
        let dropped = report(row, &notes);
        assert_eq!(misses(&dropped), 1, "{}", row.exercise);
        assert!(dropped.hit_completeness < 1.0);
    }
}

/// Warm-ups are notes like any other, even though they decide nothing.
#[test]
fn every_level_has_a_warm_up_with_schedules() {
    let rows = rows();
    for level in ["beginner", "intermediate", "advanced"] {
        let prefix = format!("warmup-{level}.");
        let count = rows.iter().filter(|r| r.exercise.starts_with(&prefix)).count();
        assert!(count >= 18, "{level}: {count} warm-up variants across three Paths");
    }
}

#[test]
fn a_constant_input_delay_is_the_known_limit_at_speed() {
    // The audit's defect 2, on one of our own Exercises: this pins it so whoever
    // adds calibration has a test that changes and a reason to re-read
    // `gradingLimits`. A slow Exercise survives a 50 ms lag; sixteenths at a
    // brisk tempo should lose notes. Should this assertion start failing because
    // calibration landed, the fast rungs can be trusted further: update both.
    let rows = rows();
    let slow = rows
        .iter()
        .find(|r| r.exercise == "even-eighths.open-string")
        .unwrap();
    let mut late = played(slow, 2.0, 21);
    late.iter_mut().for_each(|n| n.time_ms += 50.0);
    let report_slow = report(slow, &late);
    assert_eq!(hits(&report_slow), slow.schedule.onsets.len());
    assert!(report_slow.interval_consistency >= 0.85);

    let fast = rows
        .iter()
        .find(|r| r.exercise.starts_with("speed-bursts.one-beat#"))
        .unwrap();
    let mut late = played(fast, 2.0, 22);
    late.iter_mut().for_each(|n| n.time_ms += 60.0);
    let report_fast = report(fast, &late);
    assert!(
        hits(&report_fast) < fast.schedule.onsets.len(),
        "sixteenths at {} BPM with 60 ms of delay kept every note: calibration may have landed",
        fast.bpm
    );
}

/// An Exercise's `passBars`, read from the pack it ships in.
fn pass_bars(path: &str, exercise: &str) -> Option<Vec<PassBar>> {
    exercise_bars(path, exercise, true)
}

/// An Exercise's `passBars` when it is graded, looping or not.
fn graded_bars(path: &str, exercise: &str) -> Option<Vec<PassBar>> {
    exercise_bars(path, exercise, false)
}

fn exercise_bars(path: &str, exercise: &str, looping_only: bool) -> Option<Vec<PassBar>> {
    // A variant (`id#key=A,…`) is graded by its own bars when it has them,
    // and its Exercise's otherwise; grading and looping are the Exercise's.
    let (base, variant) = (exercise.split('#').next().unwrap_or(exercise), exercise);
    let pack = pack(path)?;
    let exercise = find_exercise(&pack, base)?;
    if exercise["grading"] != "graded" || (looping_only && exercise["loops"] != true) {
        return None;
    }
    let own = (variant != base).then(|| find_exercise(exercise, variant)).flatten().unwrap_or(exercise);
    serde_json::from_value(own["passBars"].clone()).ok()
}

fn pack(path: &str) -> Option<serde_json::Value> {
    let file = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../src/paths/packs")
        .join(format!("{path}.json"));
    serde_json::from_str(&fs::read_to_string(&file).ok()?).ok()
}

fn find_exercise<'a>(v: &'a serde_json::Value, id: &str) -> Option<&'a serde_json::Value> {
    match v {
        serde_json::Value::Object(m) => {
            if m.get("id").and_then(|i| i.as_str()) == Some(id) && m.contains_key("passBars") {
                return Some(v);
            }
            m.values().find_map(|x| find_exercise(x, id))
        }
        serde_json::Value::Array(a) => a.iter().find_map(|x| find_exercise(x, id)),
        _ => None,
    }
}

/// The tempos a Session plays a graded Exercise at, from its ladder: the first
/// graded rung (where a new Exercise starts, about 0.6x the pass tempo), and
/// placement's climb (`placementLadder` in `src/session/planner.ts`: the rung at
/// or under 75% of the pass tempo, the pass tempo, the rung at or under 120%).
fn ladder_tempos(path: &str, exercise: &str, pass_at: f64) -> Vec<f64> {
    let base = exercise.split('#').next().unwrap_or(exercise);
    let Some(ex) = pack(path).and_then(|p| find_exercise(&p, base).cloned()) else {
        return vec![pass_at];
    };
    let mut rungs: Vec<f64> = ex["tempo"]["rungs"]
        .as_array()
        .map(|a| a.iter().filter(|r| r["grading"] == "graded").filter_map(|r| r["bpm"].as_f64()).collect())
        .unwrap_or_default();
    rungs.sort_by(f64::total_cmp);
    let Some(&first) = rungs.first() else {
        return vec![pass_at];
    };
    let at_or_under = |t: f64| rungs.iter().copied().filter(|&r| r <= t).last().unwrap_or(first);
    let easy = pass_at.min(first.max(at_or_under(0.75 * pass_at)));
    let high = at_or_under(1.2 * pass_at);
    let mut out = vec![first, easy, pass_at];
    if high > pass_at {
        out.push(high);
    }
    out.sort_by(f64::total_cmp);
    out.dedup();
    out
}

/// Bars a Session Take has past the stretch it is judged over:
/// `TAKE_SLACK_BARS` in `src/session/grade.ts` (owner, 2026-11-17).
const TAKE_SLACK_BARS: u32 = 2;

/// A Session Take of this Exercise, exactly as `src/session/take.ts`
/// `buildTake` writes it: `takeBarsOf` bars (the longest `overBars` or the
/// clean tempo's 8, plus the slack, and at least one whole pass), as whole
/// passes and the start of one more, cut on the bar line, not looping. Bars
/// are four quarters in every pack today. Returns the schedule and its bars.
fn session_take(row: &Row, bars: &[PassBar]) -> (ScoreSchedule, u32) {
    let length = row.schedule.length_beats;
    let ex_bars = (length / 4.0).round().max(1.0) as u32;
    let needed = bars.iter().map(|b| b.over_bars).max().unwrap_or(1).max(CLEAN_TEMPO_MIN_BARS) + TAKE_SLACK_BARS;
    let take_bars = needed.max(ex_bars);
    let total = take_bars as f64 * 4.0;
    let passes = take_bars.div_ceil(ex_bars) as usize;
    let per_pass = row.schedule.onsets.len() as u32;
    let schedule = ScoreSchedule {
        onsets: (0..passes)
            .flat_map(|p| {
                row.schedule.onsets.iter().map(move |o| ExpectedOnset {
                    id: o.id + p as u32 * per_pass,
                    beat: o.beat + p as f64 * length,
                    ..o.clone()
                })
            })
            .filter(|o| o.beat < total - 1e-9)
            .collect(),
        length_beats: total,
        loops: false,
    };
    (schedule, take_bars)
}

/// Every looping graded Exercise, played right round its loop for longer than
/// its longest `overBars` and the clean tempo's 8 bars, passes its own bars.
/// A bar that a tidy player could not meet would be a content bug; one the
/// app cannot measure must say so rather than pass silently.
#[test]
fn every_looping_exercise_played_right_passes_its_own_bars() {
    let mut checked = 0;
    for (index, row) in rows().iter().enumerate() {
        let Some(bars) = pass_bars(&row.path, &row.exercise) else {
            continue;
        };
        if bars.is_empty() || row.schedule.onsets.is_empty() {
            continue;
        }
        let name = format!("{}/{}", row.path, row.exercise);
        let length = row.schedule.length_beats;
        let window = bars.iter().map(|b| b.over_bars).max().unwrap_or(1).max(CLEAN_TEMPO_MIN_BARS);
        // Bars are four quarters in every pack today; round up to whole passes.
        let passes = ((window as f64 * 4.0) / length).ceil() as usize;
        let ms = 60_000.0 / row.bpm;
        let mut rng = Xorshift64::new(500 + index as u64);
        let mut notes = Vec::new();
        for pass in 0..passes {
            for onset in &row.schedule.onsets {
                let jitter = ((rng.next_u64() % 2001) as f64 / 1000.0 - 1.0) * 2.0;
                notes.push(PlayedOnset {
                    time_ms: (pass as f64 * length + onset.beat) * ms + jitter,
                    // The written accents, played clearly louder.
                    amplitude: if onset.accent { 1.0 } else { 0.4 },
                    confidence: 1.0,
                });
            }
        }
        let looped = ScoreSchedule {
            loops: true,
            ..row.schedule.clone()
        };
        let mut run = ScheduleRun::new(looped).with_lag_correction(true).with_pass_bars(bars.clone());
        // The transport runs one bar past the last note, as a Take's does.
        for i in 0..=(passes as f64 * length) as usize + 4 {
            run.note_quarter_in_bar(i == 0, i as f64 * ms, 4);
        }
        for n in &notes {
            run.note_onset(*n);
        }
        let weights = Instrument::ElectricGuitar.profile().score_weights;
        let grade = run.report(&weights).expect("a beat map").grade;
        let pass = grade.pass.as_ref().expect("pass bars were loaded");
        assert_eq!(pass.verdict, PassVerdict::Passed, "{name}: {pass:?}");
        assert!(pass.counts_for_clean_tempo, "{name}: {pass:?}");
        let unmeasured: Vec<&String> =
            bars.iter().map(|b| &b.metric).filter(|m| *m == "noteIdentity").collect();
        assert_eq!(pass.not_assessed.len(), unmeasured.len(), "{name}: {pass:?}");
        checked += 1;
    }
    assert!(checked > 30, "only {checked} looping graded Exercises");
}

/// A Session Take, exactly as the engine logs it: the Exercise written out
/// to the Take's bars (`src/session/take.ts` `buildTake`), not looping, and the
/// transport stopping on the line after the last bar. No downbeat follows that
/// line, so the last bar has to count as finished from the pass length alone,
/// or a Take with no slack could never reach the clean tempo.
#[test]
fn a_take_played_to_its_end_finishes_every_bar() {
    let row = rows()
        .into_iter()
        .find(|r| {
            r.path == "alternate-picking"
                && pass_bars(&r.path, &r.exercise).is_some_and(|b| !b.is_empty())
                && !r.schedule.onsets.is_empty()
        })
        .expect("a graded Alternate Picking Exercise");
    let bars = pass_bars(&row.path, &row.exercise).unwrap();
    let (written, _) = session_take(&row, &bars);
    let total = written.length_beats;
    let ms = 60_000.0 / row.bpm;
    let notes: Vec<PlayedOnset> = written
        .onsets
        .iter()
        .map(|o| PlayedOnset {
            time_ms: o.beat * ms,
            amplitude: if o.accent { 1.0 } else { 0.4 },
            confidence: 1.0,
        })
        .collect();
    let weights = Instrument::ElectricGuitar.profile().score_weights;
    let grade_after = |quarters: usize| {
        let mut run = ScheduleRun::new(written.clone()).with_lag_correction(true).with_pass_bars(bars.clone());
        for i in 0..quarters {
            run.note_quarter_in_bar(i % 4 == 0, i as f64 * ms, 4);
        }
        for n in &notes {
            run.note_onset(*n);
        }
        run.report(&weights).expect("a beat map").grade.pass.expect("pass bars were loaded")
    };

    let whole = grade_after(total as usize);
    let name = format!("{}/{}", row.path, row.exercise);
    assert_eq!(whole.finished_bars, (total / 4.0) as u32, "{name}: {whole:?}");
    assert!(whole.counts_for_clean_tempo, "{name}: {whole:?}");

    // Stopped inside the last bar: that bar is not finished.
    let short = grade_after(total as usize - 1);
    assert_eq!(short.finished_bars, (total / 4.0) as u32 - 1, "{name}: {short:?}");
}

/// Songs loads a schedule with no pass bars and no lag correction, and its
/// report must be exactly what `match_attempt` gave before the revamp, lag
/// and all: a tool's numbers do not move under it.
#[test]
fn a_run_without_lag_correction_scores_like_the_plain_matcher() {
    let row = rows().into_iter().find(|r| !r.schedule.onsets.is_empty()).unwrap();
    let ms = 60_000.0 / row.bpm;
    // A constant 35 ms of rig lag: the correction would take it out; Songs does not.
    let notes: Vec<PlayedOnset> = played(&row, 2.0, 7)
        .into_iter()
        .map(|n| PlayedOnset { time_ms: n.time_ms + 35.0, ..n })
        .collect();
    let quarters = row.schedule.length_beats.ceil() as usize + 2;
    let mut run = ScheduleRun::new(row.schedule.clone()).with_calibration_seed(Some(35.0));
    for i in 0..quarters {
        run.note_quarter_in_bar(i % 4 == 0, i as f64 * ms, 4);
    }
    for n in &notes {
        run.note_onset(*n);
    }
    let weights = Instrument::ElectricGuitar.profile().score_weights;
    let from_run = run.report(&weights).expect("a beat map");
    let plain = match_attempt(
        &row.schedule,
        &BeatMap::from_quarter_times((0..quarters).map(|i| i as f64 * ms).collect()),
        &notes,
        &weights,
    );
    assert_eq!(from_run.results, plain.results);
    assert_eq!(from_run.score, plain.score);
    assert_eq!(from_run.interval_consistency, plain.interval_consistency);
}

/// Play a Session Take: every written onset with up to 2 ms of seeded jitter,
/// except those `drop` says were fluffed. Returns the pass result.
fn play_take(
    written: &ScoreSchedule,
    bars: &[PassBar],
    bpm: f64,
    seed: u64,
    drop: impl Fn(&ExpectedOnset) -> bool,
) -> PassResult {
    let ms = 60_000.0 / bpm;
    let mut rng = Xorshift64::new(seed);
    let mut run = ScheduleRun::new(written.clone()).with_lag_correction(true).with_pass_bars(bars.to_vec());
    for i in 0..(written.length_beats as usize) {
        run.note_quarter_in_bar(i % 4 == 0, i as f64 * ms, 4);
    }
    for o in &written.onsets {
        let jitter = ((rng.next_u64() % 2001) as f64 / 1000.0 - 1.0) * 2.0;
        if drop(o) {
            continue;
        }
        run.note_onset(PlayedOnset {
            time_ms: o.beat * ms + jitter,
            amplitude: if o.accent { 1.0 } else { 0.4 },
            confidence: 1.0,
        });
    }
    let weights = Instrument::ElectricGuitar.profile().score_weights;
    let grade = run.report(&weights).expect("a beat map").grade;
    grade.pass.expect("pass bars were loaded")
}

/// Every graded Exercise of every runnable Path, as a Session plays it: written
/// out to `takeBarsOf` bars (`src/session/grade.ts`, `take.ts` `buildTake`):
/// the clean tempo's 8 bars or its longest `overBars`, two bars of slack, and
/// the last pass cut on a bar line, not looping, the transport stopping on the
/// last bar line. Played right, each passes its own bars and counts toward the
/// clean tempo. Looping or not, and every variant: this is the check that a
/// Path is fit to be runnable.
///
/// At every tempo of its ladder a Session plays it at (`ladder_tempos`): the
/// first rung, and placement's climb around the pass tempo.
///
/// And with the slack, the owner's rule of 2026-11-17: the first bar fluffed
/// (every note of it missed) or the last, the Take still passes and still
/// earns the clean tempo from the clean bars in a row that are left.
#[test]
fn every_graded_exercise_of_a_runnable_path_passes_as_a_session_take() {
    let mut checked = std::collections::BTreeMap::<String, usize>::new();
    for (index, row) in rows().iter().enumerate() {
        let Some(bars) = graded_bars(&row.path, &row.exercise) else {
            continue;
        };
        if bars.is_empty() || row.schedule.onsets.is_empty() {
            continue;
        }
        let name = format!("{}/{}", row.path, row.exercise);
        let (written, take_bars) = session_take(row, &bars);
        let seed = 900 + index as u64;
        let total = written.length_beats;
        for bpm in ladder_tempos(&row.path, &row.exercise, row.bpm) {
            let pass = play_take(&written, &bars, bpm, seed, |_| false);
            assert_eq!(pass.verdict, PassVerdict::Passed, "{name} at {bpm}: {pass:?}");
            assert!(pass.counts_for_clean_tempo, "{name} at {bpm}: {pass:?}");
            assert_eq!(pass.finished_bars, take_bars, "{name} at {bpm}");

            for (which, fluffed) in [("first", 0.0..4.0), ("last", total - 4.0..total)] {
                let pass = play_take(&written, &bars, bpm, seed, |o| fluffed.contains(&o.beat));
                assert_eq!(pass.verdict, PassVerdict::Passed, "{name} at {bpm}, {which} bar fluffed: {pass:?}");
                assert!(pass.counts_for_clean_tempo, "{name} at {bpm}, {which} bar fluffed: {pass:?}");
            }
        }
        *checked.entry(row.path.clone()).or_default() += 1;
    }
    println!("{checked:?}");
    assert!(checked.get("alternate-picking").copied().unwrap_or(0) > 30, "{checked:?}");
    assert!(checked.get("sweep-picking").copied().unwrap_or(0) > 100, "{checked:?}");
    assert!(checked.get("shred").copied().unwrap_or(0) > 150, "{checked:?}");
    // The Theory Paths: written licks, phrases and arpeggios, with timing bars.
    assert!(checked.get("blues-pentatonics").copied().unwrap_or(0) >= 30, "{checked:?}");
    assert!(checked.get("classic-rock").copied().unwrap_or(0) >= 24, "{checked:?}");
    // The Paths added on mvp-paths-content (`plans/paths/NEW_PATHS.md`).
    assert!(checked.get("legato").copied().unwrap_or(0) > 100, "{checked:?}");
    assert!(checked.get("rhythm-foundations").copied().unwrap_or(0) > 100, "{checked:?}");
    assert!(checked.get("metal-rhythm").copied().unwrap_or(0) >= 40, "{checked:?}");
    assert!(checked.get("know-the-neck").copied().unwrap_or(0) >= 50, "{checked:?}");
    assert!(checked.get("scales-and-modes").copied().unwrap_or(0) >= 50, "{checked:?}");
    assert!(checked.get("tapping").copied().unwrap_or(0) >= 40, "{checked:?}");
    assert!(checked.get("funk-lines").copied().unwrap_or(0) >= 30, "{checked:?}");
    assert!(checked.get("triads").copied().unwrap_or(0) >= 40, "{checked:?}");
}
